// The rest of chandigital.in saves the visitor's choice under this key, so a
// language picked on the product page carries over here, and vice versa.
const STORAGE_KEY = "rallypoint-lang";

export function pickLanguage() {
  const byId = (id) => LANGUAGES.find((l) => l.id === id);
  const bySite = (code) => LANGUAGES.find((l) => l.site === code);
  const param = new URLSearchParams(location.search).get("lang");
  if (param && (byId(param) || bySite(param))) return (byId(param) || bySite(param)).id;
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved && bySite(saved)) return bySite(saved).id;
  } catch (e) {}
  for (const pref of navigator.languages || [navigator.language || "en"]) {
    const p = pref.toLowerCase();
    for (const l of LANGUAGES) {
      if (l.match.some((m) => p === m || p.startsWith(m + "-"))) return l.id;
    }
  }
  return "en";
}

export function rememberLanguage(id) {
  const l = LANGUAGES.find((x) => x.id === id);
  try {
    if (!l || l.site === "en") localStorage.removeItem(STORAGE_KEY);
    else localStorage.setItem(STORAGE_KEY, l.site);
  } catch (e) {}
}
